36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "postcode")
65	    private String postcode;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "member_id")
74	    private String memberId;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "household_size")
83	    private Integer householdSize;
84	
85	    @Column(name = "membership_level_cap")
86	    private Integer membershipLevelCap;
87	
88	    @Column(name = "possible_duplicate")
89	    private Boolean possibleDuplicate;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @Column(name = "deleted", nullable = false)
95	    private boolean deleted = false;
96	
97	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
98	    private Set<Pet> pets;
99	
100	    public String getTitle() {
101	        return this.title;
102	    }
103	
104	    public void setTitle(String title) {
105	        this.title = title;
106	    }
107	
108	    /**
109	     * The owner's salutation: the {@link #getTitle() title} followed by a space and the last name
110	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title has
111	     * been supplied.
112	     */
113	    public String getSalutation() {
114	        if (this.title == null || this.title.isEmpty()) {
115	            return this.getLastName();
116	        }
117	        return this.title + " " + this.getLastName();
118	    }
119	
120	    public String getAddress() {
121	        return this.address;
122	    }
123	
124	    public void setAddress(String address) {
125	        this.address = address;
126	    }
127	
128	    public String getAddressLine1() {
129	        return this.addressLine1;
130	    }
131	
132	    public void setAddressLine1(String addressLine1) {
133	        this.addressLine1 = addressLine1;
134	    }
135	
136	    public String getAddressLine2() {
137	        return this.addressLine2;
138	    }
139	
140	    public void setAddressLine2(String addressLine2) {
141	        this.addressLine2 = addressLine2;
142	    }
143	
144	    public String getCity() {
145	        return this.city;
146	    }
147	
148	    public void setCity(String city) {
149	        this.city = city;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    /**
161	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
162	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
163	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
164	     * been set.
165	     */
166	    public String getTelephoneDisplay() {
167	        return Telephone.forDisplay(this.telephone);
168	    }
169	
170	    public String getEmail() {
171	        return this.email;
172	    }
173	
174	    public void setEmail(String email) {
175	        this.email = email;
176	    }
177	
178	    public String getPostcode() {
179	        return this.postcode;
180	    }
181	
182	    public void setPostcode(String postcode) {
183	        this.postcode = postcode;
184	    }
185	
186	    public LocalDate getRegistrationDate() {
187	        return this.registrationDate;
188	    }
189	
190	    public void setRegistrationDate(LocalDate registrationDate) {
191	        this.registrationDate = registrationDate;
192	    }
193	
194	    public LocalDate getBirthDate() {
195	        return this.birthDate;
196	    }
197	
198	    public void setBirthDate(LocalDate birthDate) {
199	        this.birthDate = birthDate;
200	    }
201	
202	    public String getMemberId() {
203	        return this.memberId;
204	    }
205	
206	    public void setMemberId(String memberId) {
207	        this.memberId = memberId;
208	    }
209	
210	    /**
211	     * The owner's current primary identifier: the single external identifier by which this owner is
212	     * known, namely the {@link #getMemberId() member id}. Every consumer that records the primary
213	     * identifier reads it through this method, so a future change of primary identifier follows
214	     * automatically.
215	     */
216	    public String getPrimaryIdentifier() {
217	        return getMemberId();
218	    }
219	
220	    public String getHouseholdId() {
221	        return this.householdId;
222	    }
223	
224	    public void setHouseholdId(String householdId) {
225	        this.householdId = householdId;
226	    }
227	
228	    public Integer getNamesakeCount() {
229	        return this.namesakeCount;
230	    }
231	
232	    public void setNamesakeCount(Integer namesakeCount) {
233	        this.namesakeCount = namesakeCount;
234	    }
235	
236	    public Integer getHouseholdSize() {
237	        return this.householdSize;
238	    }
239	
240	    public void setHouseholdSize(Integer householdSize) {
241	        this.householdSize = householdSize;
242	    }
243	
244	    /**
245	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: one above
246	     * the highest membership level held by the owner's household members when this owner was created.
247	     * {@code null} when the owner had no existing household member and so is uncapped.
248	     */
249	    public Integer getMembershipLevelCap() {
250	        return this.membershipLevelCap;
251	    }
252	
253	    public void setMembershipLevelCap(Integer membershipLevelCap) {
254	        this.membershipLevelCap = membershipLevelCap;
255	    }
256	
257	    /**
258	     * Whether this owner, though not a hard duplicate, matches an existing owner's last name by
259	     * Soundex and shares its postcode while holding a different identity key. Resolved at creation
260	     * and stored so it is reported consistently on every later read.
261	     */
262	    public Boolean getPossibleDuplicate() {
263	        return this.possibleDuplicate;
264	    }
265	
266	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
267	        this.possibleDuplicate = possibleDuplicate;
268	    }
269	
270	    /**
271	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
272	     * is not a possible duplicate.
273	     */
274	    public Integer getPossibleDuplicateOf() {
275	        return this.possibleDuplicateOf;
276	    }
277	
278	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
279	        this.possibleDuplicateOf = possibleDuplicateOf;
280	    }
281	
282	    /**
283	     * Whether this owner has been soft-deleted. A soft-deleted owner keeps its row and remains
284	     * retrievable, but is ignored by the create endpoint's duplicate and identity checks. A newly
285	     * created owner is never deleted.
286	     */
287	    public boolean isDeleted() {
288	        return this.deleted;
289	    }
290	
291	    public void setDeleted(boolean deleted) {
292	        this.deleted = deleted;
293	    }
294	
295	    /**
296	     * The owner's identity key: the single derived value used to detect duplicate owners, formed as
297	     * the SHA-256 hex digest of
298	     * {@code <versionTag> + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}
299	     * where an absent telephone or email contributes an empty string. The leading
300	     * {@link IdentityVersion#TAG version tag} makes every version-2 key differ from the value the
301	     * same owner would have produced under version 1. Because the telephone is part of the key,
302	     * housemates that share a last name and postcode but hold different telephones have distinct
303	     * identity keys and are both allowed (and merely flagged as possible duplicates).
304	     */
305	    public String getIdentityKey() {
306	        String key = IdentityVersion.TAG + "|" + orEmpty(this.telephone) + "|" + orEmpty(this.email)
307	            + "|" + Soundex.of(this.getLastName());
308	        return Sha256.hex(key);
309	    }
310	
311	    private static String orEmpty(String value) {
312	        return value == null ? "" : value;
313	    }
314	
315	    /**
316	     * The owner's fiscal year, formatted {@code 'FY<YY>'}: the FY segment carried by the
317	     * {@link #getMemberId() member id} (the fiscal year, starting 1 July, of the business-day-adjusted
318	     * registration date when the identity was assigned; see {@link FiscalYear}). Absent until a member
319	     * id has been assigned.
320	     */
321	    public String getFiscalYear() {
322	        if (this.memberId == null) {
323	            return null;
324	        }
325	        return FiscalYear.label(effectiveRegistrationDate());
326	    }
327	
328	    /**
329	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July boundaries crossed
330	     * from the {@link #getRegistrationDate() registration date} up to today (see {@link FiscalYear}).
331	     * An owner still in their registration fiscal year has a tenure of zero. Absent until a
332	     * registration date is present.
333	     */
334	    public Long getTenureFiscalYears() {
335	        if (this.registrationDate == null) {
336	            return null;
337	        }
338	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
339	    }
340	
341	    /**
342	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
343	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
344	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
345	     * points once the owner's {@link #getTenureFiscalYears() tenure} spans at least one full fiscal
346	     * year (the registration and current dates fall in different fiscal years).
347	     */
348	    public Integer getMembershipPoints() {
349	        int points = 0;
350	        boolean hasEmail = this.email != null && !this.email.isEmpty();
351	        if (hasEmail) {
352	            points += 2;
353	        }
354	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
355	        if (unique) {
356	            points += 1;
357	        }
358	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
359	        if (sharedHousehold) {
360	            points += 2;
361	        }
362	        Long tenureFiscalYears = getTenureFiscalYears();
363	        boolean tenured = tenureFiscalYears != null && tenureFiscalYears >= 1;
364	        if (tenured) {
365	            points += 3;
366	        }
367	        return points;
368	    }
369	
370	    /**
371	     * The owner's membership level, a number from 1 to 4 derived from the owner's
372	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
373	     * 4 for 6 or more. The level is then held to its {@link #getMembershipLevelCap() cap} (one above
374	     * the highest level among the owner's household members at creation), so a new owner cannot rank
375	     * more than one level above their household. An uncapped owner keeps the derived level.
376	     */
377	    public Integer getMembershipLevel() {
378	        int level = derivedMembershipLevel();
379	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
380	            return this.membershipLevelCap;
381	        }
382	        return level;
383	    }
384	
385	    private int derivedMembershipLevel() {
386	        int points = getMembershipPoints();
387	        if (points >= 6) {
388	            return 4;
389	        }
390	        if (points >= 4) {
391	            return 3;
392	        }
393	        if (points >= 2) {
394	            return 2;
395	        }
396	        return 1;
397	    }
398	
399	    /**
400	     * The owner's locality: the plain region derived from the owner's postcode (see
401	     * {@link Regions#regionOfPostcode(String)}), or {@link Regions#UNKNOWN} when no known region
402	     * applies. This is the user-facing region and never carries the identity {@link IdentityVersion#TAG
403	     * version tag}, unlike the region embedded inside the {@link #getMemberId() member id}.
404	     */
405	    public String getLocality() {
406	        return Regions.regionOfPostcode(this.postcode);
407	    }
408	
409	    /**
410	     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
411	     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
412	     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
413	     */
414	    public String getTimezone() {
415	        return Regions.timezoneOf(getLocality());
416	    }
417	
418	    /**
419	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}. TIER is {@code "PREMIUM"} when the
420	     * owner's {@link #getMembershipLevel() membership level} is 3 or more, otherwise
421	     * {@code "STANDARD"}. AREA is {@code "METRO"} when the owner's {@link #getLocality() locality} is
422	     * a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}.
423	     */
424	    public String getOwnerSegment() {
425	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
426	        String area = Regions.isKnown(getLocality()) ? "METRO" : "REGIONAL";
427	        return tier + "_" + area;
428	    }
429	
430	    /**
431	     * The owner's preferred contact channel, derived from the owner's own fields:
432	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
433	     */
434	    public String getContactPreference() {
435	        boolean hasEmail = this.email != null && !this.email.isEmpty();
436	        return hasEmail ? "EMAIL" : "PHONE";
437	    }
438	
439	    /**
440	     * The owner's age band, derived from the owner's own fields: the whole years between
441	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
442	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
443	     * (65 or older). Absent until a birth date and a registration date are both present.
444	     */
445	    public String getAgeBand() {
446	        if (this.birthDate == null || this.registrationDate == null) {
447	            return null;
448	        }
449	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
450	        if (age < 18) {
451	            return "MINOR";
452	        }
453	        return age < 65 ? "ADULT" : "SENIOR";
454	    }
455	
456	    /**
457	     * The registration date this owner will be persisted with: the supplied
458	     * {@link #getRegistrationDate() registration date} rolled forward to a business day, or today's
459	     * business-day-adjusted date when none was supplied. Every value derived from the registration
460	     * date (such as the FY segment of the {@link #getMemberId() member id}) uses this date, so a
461	     * caller assigning the identity before persistence obtains the same value that
462	     * {@link #resolveRegistrationDate() persistence} later stores.
463	     */
464	    public LocalDate effectiveRegistrationDate() {
465	        LocalDate date = this.registrationDate != null ? this.registrationDate : LocalDate.now();
466	        return BusinessDay.onOrAfter(date);
467	    }
468	
469	    /**
470	     * Resolve the effective registration date before persisting so a newly registered owner always
471	     * has a business-day registration date, defaulted to today when none was supplied. Idempotent:
472	     * a date already resolved via {@link #effectiveRegistrationDate()} is left unchanged.
473	     */
474	    @PrePersist
475	    private void resolveRegistrationDate() {
476	        this.registrationDate = effectiveRegistrationDate();
477	    }
478	
479	    /**
480	     * The owner's self link: the canonical API path of this owner, formatted
481	     * {@code "/api/owners/<id>"}. Absent until the owner has been assigned an id.
482	     */
483	    public String getSelfLink() {
484	        if (this.getId() == null) {
485	            return null;
486	        }
487	        return "/api/owners/" + this.getId();
488	    }
489	
490	    protected Set<Pet> getPetsInternal() {
491	        if (this.pets == null) {
492	            this.pets = new HashSet<>();
493	        }
494	        return this.pets;
495	    }
496	
497	    protected void setPetsInternal(Set<Pet> pets) {
498	        this.pets = pets;
499	    }
500	
501	    public List<Pet> getPets() {
502	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
503	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
504	        return Collections.unmodifiableList(sortedPets);
505	    }
506	
507	    public void setPets(List<Pet> pets) {
508	        this.pets = new HashSet<>(pets);
509	    }
510	
511	    public void addPet(Pet pet) {
512	        getPetsInternal().add(pet);
513	        pet.setOwner(this);
514	    }
515	
516	    /**
517	     * Return the Pet with the given name, or null if none found for this Owner.
518	     *
519	     * @param name to test
520	     * @return true if pet name is already in use
521	     */
522	    public Pet getPet(String name) {
523	        return getPet(name, false);
524	    }
525	
526	    /**
527	     * Return the Pet with the given name, or null if none found for this Owner.
528	     *
529	     * @param name to test
530	     * @return true if pet name is already in use
531	     */
532	    public Pet getPet(String name, boolean ignoreNew) {
533	        name = name.toLowerCase();
534	        for (Pet pet : getPetsInternal()) {
535	            if (!ignoreNew || !pet.isNew()) {
536	                String compName = pet.getName();
537	                compName = compName.toLowerCase();
538	                if (compName.equals(name)) {
539	                    return pet;
540	                }
541	            }
542	        }
543	        return null;
544	    }
545	
546	    public Pet getPet(Integer petId) {
547	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
548	    }
549	
550	    @Override
551	    public String toString() {
552	        return new ToStringCreator(this)
553	
554	            .append("id", this.getId())
555	            .append("new", this.isNew())
556	            .append("lastName", this.getLastName())
557	            .append("firstName", this.getFirstName())
558	            .append("address", this.address)
559	            .append("city", this.city)
560	            .append("telephone", this.telephone)
561	            .append("email", this.email)
562	            .toString();
563	    }
564	}
