233	        }
234	        HttpHeaders headers = new HttpHeaders();
235	        headers.setLocation(UriComponentsBuilder.newInstance()
236	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
237	        return new ResponseEntity<>(toOwnerDto(owner), headers, HttpStatus.CREATED);
