240	    /**
241	     * Apply every create-time rule to the submitted fields and persist the resulting owner.
242	     */
243	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
244	        this.addressFormNormalizer.normalize(ownerFieldsDto);
245	        this.ownerRequestValidator.validate(ownerFieldsDto);
246	        this.postcodeValidator.validate(ownerFieldsDto);
247	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
248	        this.registrationDateValidator.validate(ownerFieldsDto.getRegistrationDate());
249	        this.dailyOwnerLimitValidator.validate(ownerFieldsDto.getRegistrationDate());
250	        ownerFieldsDto.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
251	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
252	        this.disposableEmailDomainValidator.validate(ownerFieldsDto.getEmail());
253	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
254	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
255	        // The householdId is deterministic from (lastName, postcode), so every owner carries the
256	        // identifier of its household automatically.
257	        owner.setHouseholdId(
258	            this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
259	        if (sharesHousehold) {
260	            // A declared household member is deliberately allowed and, being declared, is never a
261	            // suspected duplicate.
262	            owner.setPossibleDuplicate(false);
263	            owner.setPossibleDuplicateOf(null);
264	        } else {
265	            this.duplicateOwnerValidator.validate(owner);
266	            Integer possibleDuplicateOf = this.possibleDuplicateDetector.findPossibleDuplicate(owner);
267	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
268	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
269	        }
270	        owner.setMemberId(this.memberIdGenerator.generate(owner));
271	        owner.setNamesakeCount(
272	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
273	        owner.setHouseholdSize(this.householdSizeCalculator.size(owner));
274	        owner.setMembershipLevelCap(this.membershipLevelCapCalculator.cap(owner));
275	        this.clinicService.saveOwner(owner);
276	        this.ownerAuditLogger.created(owner);
277	        this.welcomeNotifier.welcome(owner);
278	        return owner;
279	    }
