23	/**
24	 * Reconciles the two accepted address forms into a single canonical, normalized address before an
25	 * owner is validated and stored. The structured form ({@code addressLine1} with an optional
26	 * {@code addressLine2}) is preferred when present; otherwise the flat {@code address} is kept for
27	 * backward compatibility. Whichever fields are supplied are normalized with the shared
28	 * {@link AddressNormalizer}, and the flat {@code address} is (re)composed as the normalized first
29	 * line with the normalized second line appended after a single space when a second line is present.
30	 * Every later consumer therefore reads one normalized, composed address.
31	 */
32	@Component
33	public class AddressFormNormalizer {
34	
35	    private final AddressNormalizer addressNormalizer;
36	
37	    public AddressFormNormalizer(AddressNormalizer addressNormalizer) {
38	        this.addressNormalizer = addressNormalizer;
39	    }
40	
41	    /**
42	     * Normalize the supplied address fields in place and compose the flat {@code address}.
43	     *
44	     * @param owner the submitted owner fields, mutated so its address fields hold their normalized,
45	     * composed values
46	     */
47	    public void normalize(OwnerFieldsDto owner) {
48	        String line1 = this.addressNormalizer.normalize(owner.getAddressLine1());
49	        if (StringUtils.hasText(line1)) {
50	            String line2 = this.addressNormalizer.normalize(owner.getAddressLine2());
51	            boolean hasLine2 = StringUtils.hasText(line2);
52	            owner.setAddressLine1(line1);
53	            owner.setAddressLine2(hasLine2 ? line2 : null);
54	            owner.setAddress(hasLine2 ? line1 + " " + line2 : line1);
55	        }
56	        else {
57	            owner.setAddress(this.addressNormalizer.normalize(owner.getAddress()));
58	        }
59	    }
60	}
