18	
19	import org.springframework.samples.petclinic.model.Telephone;
20	import org.springframework.samples.petclinic.rest.error.InvalidTelephoneException;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Normalizes a submitted telephone number into E.164 form. A leading '+' and country code are kept
25	 * when present; otherwise the default country code '+61' is assumed and a single leading '0' is
26	 * dropped from the national digits. Spaces, dashes and brackets are stripped, and the result must
27	 * hold between 8 and 15 digits after the '+'. For known country codes the national number must also
28	 * be exactly the length that country requires ('+61' => 9 national digits, '+1' => 10).
29	 */
30	@Component
31	public class TelephoneNormalizer {
32	
33	    private static final String DEFAULT_COUNTRY_CODE = "61";
34	
35	    /** Characters used only for human-readable grouping and removed before parsing. */
36	    private static final String FORMATTING_CHARS = "[\\s\\-()\\[\\]]";
37	
38	    private static final int MIN_DIGITS = 8;
39	    private static final int MAX_DIGITS = 15;
40	
41	    /**
42	     * @param telephone the raw, possibly formatted telephone number
43	     * @return the telephone in E.164 form (a '+' followed by 8 to 15 digits)
44	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
45	     */
46	    public String normalize(String telephone) {
47	        if (telephone == null) {
48	            throw new InvalidTelephoneException(null);
49	        }
50	        String cleaned = telephone.trim().replaceAll(FORMATTING_CHARS, "");
51	        String digits;
52	        if (cleaned.startsWith("+")) {
53	            digits = cleaned.substring(1);
54	        } else {
55	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
56	            digits = DEFAULT_COUNTRY_CODE + national;
57	        }
58	        if (!digits.matches("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
59	            throw new InvalidTelephoneException(telephone);
60	        }
61	        requireValidNationalLength(digits, telephone);
62	        return "+" + digits;
63	    }
64	
65	    /**
66	     * Rejects a normalized number whose national part is the wrong length for its country code. Only
67	     * known country codes are checked; a number with an unrecognised country code passes.
68	     */
69	    private void requireValidNationalLength(String digits, String telephone) {
70	        String countryCode = Telephone.countryCodeOf(digits);
71	        if (countryCode == null) {
72	            return;
73	        }
74	        int nationalLength = digits.length() - countryCode.length();
75	        if (nationalLength != Telephone.nationalLength(countryCode)) {
76	            throw new InvalidTelephoneException(telephone);
77	        }
78	    }
79	}
