25	
26	/**
27	 * Normalizes an optionally-submitted email address: a present value must be a syntactically valid
28	 * address and is returned lower-cased, while an absent (null or blank) value is left unset.
29	 */
30	@Component
31	public class EmailNormalizer {
32	
33	    /**
34	     * A single {@code @} separating a non-empty local part from a domain that carries at least one
35	     * dot-separated label; no whitespace is allowed anywhere.
36	     */
37	    private static final Pattern EMAIL_PATTERN =
38	        Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
39	
40	    /**
41	     * @param email the raw, optionally-submitted email address
42	     * @return the trimmed, lower-cased address, or {@code null} when no address was supplied
43	     * @throws InvalidEmailException if a value is present but not a syntactically valid address
44	     */
45	    public String normalize(String email) {
46	        if (!StringUtils.hasText(email)) {
47	            return null;
48	        }
49	        String trimmed = email.trim();
50	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
51	            throw new InvalidEmailException(email);
52	        }
53	        return trimmed.toLowerCase(Locale.ROOT);
54	    }
55	}
