23	
24	/**
25	 * Rejects creating an owner that hard-duplicates an existing one. A new owner is a duplicate only
26	 * when its whole {@link Owner#getIdentityKey() identity key} (a hash of normalized telephone, email
27	 * and the Soundex of the last name) equals that of an existing owner, so housemates that share a
28	 * last name and postcode but hold different telephones are allowed (and merely flagged as
29	 * {@link PossibleDuplicateDetector possible duplicates}). The caller bypasses this check when the
30	 * create deliberately declares a shared household.
31	 */
32	@Component
33	public class DuplicateOwnerValidator {
34	
35	    private final ClinicService clinicService;
36	
37	    public DuplicateOwnerValidator(ClinicService clinicService) {
38	        this.clinicService = clinicService;
39	    }
40	
41	    /**
42	     * @param owner the owner being created, with its telephone, email and household id already
43	     * resolved so its {@link Owner#getIdentityKey() identityKey} is final
44	     * @throws DuplicateOwnerException if another owner already holds the same identity key
45	     */
46	    public void validate(Owner owner) {
47	        String identityKey = owner.getIdentityKey();
48	        boolean duplicate = this.clinicService.findAllOwners().stream()
49	            .filter(existing -> !existing.isDeleted())
50	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
51	        if (duplicate) {
52	            throw new DuplicateOwnerException(identityKey);
53	        }
54	    }
55	}
