18	
19	import java.util.Comparator;
20	import java.util.Objects;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.model.Soundex;
24	import org.springframework.samples.petclinic.service.ClinicService;
25	import org.springframework.stereotype.Component;
26	import org.springframework.util.StringUtils;
27	
28	/**
29	 * Detects a soft match between a newly created owner and an existing one: an owner that is not a
30	 * hard {@link DuplicateOwnerValidator duplicate} but whose last name (compared phonetically by
31	 * Soundex) and postcode match an existing owner while their {@link Owner#getIdentityKey() identity
32	 * keys} differ. Unlike the duplicate validator this never rejects the create; it merely reports the
33	 * existing owner so the caller can flag the new one as a possible duplicate.
34	 */
35	@Component
36	public class PossibleDuplicateDetector {
37	
38	    private final ClinicService clinicService;
39	
40	    public PossibleDuplicateDetector(ClinicService clinicService) {
41	        this.clinicService = clinicService;
42	    }
43	
44	    /**
45	     * @param owner the owner being created, with its telephone and email already normalized so its
46	     * {@link Owner#getIdentityKey() identityKey} is final
47	     * @return the id of the lowest-id existing owner whose last name (by Soundex) and postcode match
48	     * this owner's but whose identity key differs, or {@code null} when there is no such match
49	     */
50	    public Integer findPossibleDuplicate(Owner owner) {
51	        if (!StringUtils.hasText(owner.getPostcode())) {
52	            return null;
53	        }
54	        String soundex = Soundex.of(owner.getLastName());
55	        String identityKey = owner.getIdentityKey();
56	        return this.clinicService.findAllOwners().stream()
57	            .filter(existing -> !existing.isDeleted())
58	            .filter(existing -> soundex.equals(Soundex.of(existing.getLastName())))
59	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
60	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
61	            .map(Owner::getId)
62	            .filter(Objects::nonNull)
63	            .min(Comparator.naturalOrder())
64	            .orElse(null);
65	    }
66	}
