24	/**
25	 * Derives an owner's {@code householdId}: a stable identifier shared by every owner in the same
26	 * household. Because it is a pure function of the {@link HouseholdKey} over (last name, postcode),
27	 * owners with the same last name and postcode always yield the same value: the first 12 hex
28	 * characters of the SHA-256 of the {@link IdentityVersion#TAG version tag} mixed with that key. The
29	 * leading version tag makes every version-2 household id differ from the value the same household
30	 * would have produced under version 1.
31	 */
32	@Component
33	public class HouseholdIdGenerator {
34	
35	    private final HouseholdKey householdKey;
36	
37	    public HouseholdIdGenerator(HouseholdKey householdKey) {
38	        this.householdKey = householdKey;
39	    }
40	
41	    /**
42	     * @param lastName the owner's last name
43	     * @param postcode the owner's postcode
44	     * @return the stable household identifier for that last name and postcode
45	     */
46	    public String generate(String lastName, String postcode) {
47	        String key = this.householdKey.of(lastName, postcode);
48	        return Sha256.hex(IdentityVersion.TAG + "|" + key).substring(0, 12);
49	    }
