18	
19	import java.util.HashSet;
20	import java.util.Locale;
21	import java.util.Set;
22	
23	import org.springframework.samples.petclinic.model.FiscalYear;
24	import org.springframework.samples.petclinic.model.IdentityVersion;
25	import org.springframework.samples.petclinic.model.Luhn;
26	import org.springframework.samples.petclinic.model.Owner;
27	import org.springframework.samples.petclinic.model.Regions;
28	import org.springframework.samples.petclinic.model.Sha256;
29	import org.springframework.samples.petclinic.service.ClinicService;
30	import org.springframework.stereotype.Component;
31	
32	/**
33	 * Builds an owner's {@code memberId}, formatted {@code '<REGION><FY><HASH8><CHK>'}: REGION is the
34	 * version-2 identity region &mdash; the {@link IdentityVersion#TAG version tag} followed by the plain
35	 * region derived from the postcode (see {@link Regions#regionOfPostcode(String)}), e.g. {@code 'V2NSW'}
36	 * &mdash; so it differs from the plain user-facing region; FY is the two-digit fiscal year of the
37	 * business-day-adjusted registration date, HASH8 is the first 8 upper-case hex characters of SHA-256
38	 * over the normalized telephone concatenated with the last name (the same HASH8 as the
39	 * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits of
40	 * {@code <REGION><FY><HASH8>} (e.g. {@code 'V2NSW271A2B3C4D5'}).
41	 *
42	 * <p>When the formatted member id collides with an existing owner's {@code memberId}, {@code '-<n>'}
43	 * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
44	 * always receive distinct member ids.
45	 */
46	@Component
47	public class MemberIdGenerator {
48	
49	    private static final int HASH_LENGTH = 8;
50	
51	    private final ClinicService clinicService;
52	
53	    public MemberIdGenerator(ClinicService clinicService) {
54	        this.clinicService = clinicService;
55	    }
56	
57	    /**
58	     * @param owner the owner whose member id is being assigned; its postcode fixes the REGION, its
59	     * effective registration date the FY, and its telephone and last name the HASH8
60	     * @return the formatted member id, de-duplicated against existing owners
61	     */
62	    public String generate(Owner owner) {
63	        String region = IdentityVersion.TAG + Regions.regionOfPostcode(owner.getPostcode());
64	        String fiscalYear = FiscalYear.twoDigit(owner.effectiveRegistrationDate());
65	        String hash8 = Sha256.hex(owner.getTelephone() + owner.getLastName())
66	            .substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
67	        String base = region + fiscalYear + hash8;
68	        return deduplicate(base + Luhn.checkDigit(base));
69	    }
70	
71	    /**
72	     * Return {@code memberId} if no existing owner already uses it; otherwise append {@code '-<n>'}
73	     * with the smallest {@code n >= 2} that is not yet taken.
74	     */
75	    private String deduplicate(String memberId) {
76	        Set<String> existing = existingMemberIds();
77	        if (!existing.contains(memberId)) {
78	            return memberId;
79	        }
80	        for (int n = 2; ; n++) {
81	            String candidate = memberId + "-" + n;
82	            if (!existing.contains(candidate)) {
83	                return candidate;
84	            }
85	        }
86	    }
87	
88	    private Set<String> existingMemberIds() {
89	        Set<String> ids = new HashSet<>();
90	        for (Owner owner : this.clinicService.findAllOwners()) {
91	            String id = owner.getMemberId();
92	            if (id != null) {
93	                ids.add(id);
94	            }
95	        }
96	        return ids;
97	    }
98	}
