19	import java.util.List;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Computes the membership-level ceiling for a joining owner: a new owner may not rank more than one
26	 * level above their household, so the cap is one above the highest membership level currently held
27	 * by the owner's household members. When the owner has no existing household member there is no
28	 * ceiling.
29	 */
30	@Component
31	public class MembershipLevelCapCalculator {
32	
33	    private final HouseholdMembers householdMembers;
34	
35	    public MembershipLevelCapCalculator(HouseholdMembers householdMembers) {
36	        this.householdMembers = householdMembers;
37	    }
38	
39	    /**
40	     * @param owner the owner being created, not yet saved
41	     * @return one above the maximum membership level among {@code owner}'s existing household
42	     * members, or {@code null} when the owner has no existing household member and so is uncapped
43	     */
44	    public Integer cap(Owner owner) {
45	        List<Owner> members = this.householdMembers.existing(owner);
46	        if (members.isEmpty()) {
47	            return null;
48	        }
49	        int max = 0;
50	        for (Owner member : members) {
51	            max = Math.max(max, member.getMembershipLevel());
52	        }
53	        return max + 1;
54	    }
55	}
