27	/**
28	 * Finds the existing members of an owner's household. A household is keyed on (last name, postcode)
29	 * via {@link HouseholdKey}, so the members are simply the already-persisted owners that share the
30	 * given owner's key. This is the single place that resolves household membership, keeping every
31	 * household-derived value (size, membership-level ceiling) in agreement.
32	 */
33	@Component
34	public class HouseholdMembers {
35	
36	    private final ClinicService clinicService;
37	
38	    private final HouseholdKey householdKey;
39	
40	    public HouseholdMembers(ClinicService clinicService, HouseholdKey householdKey) {
41	        this.clinicService = clinicService;
42	        this.householdKey = householdKey;
43	    }
44	
45	    /**
46	     * @param owner the owner being created, not yet saved
47	     * @return every existing owner in {@code owner}'s household, i.e. sharing its last name and
48	     * postcode; empty when {@code owner} is the first member of its household
49	     */
50	    public List<Owner> existing(Owner owner) {
51	        String key = this.householdKey.of(owner.getLastName(), owner.getPostcode());
52	        List<Owner> members = new ArrayList<>();
53	        for (Owner existing : this.clinicService.findAllOwners()) {
54	            if (this.householdKey.of(existing.getLastName(), existing.getPostcode()).equals(key)) {
55	                members.add(existing);
56	            }
57	        }
58	        return members;
59	    }
60	}
