36	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
37	
38	    private static final ObjectMapper MAPPER = JsonMapper.builder().build();
39	
40	    /** Assigns each emitted create event a sequence number that strictly increases across creates. */
41	    private final AtomicLong sequence = new AtomicLong();
