22	/**
23	 * Decides whether a city is approaching the {@link CityOwnerLimitValidator#MAX_OWNERS_PER_CITY}
24	 * owner capacity limit: it is once the city already holds at least
25	 * {@value #WARNING_THRESHOLD} owners while still below the hard limit. The
26	 * {@value #WARNING_THRESHOLD}-owner threshold is the city's <em>soft capacity</em>.
27	 */
28	@Component
29	public class CityCapacityWarningEvaluator {
30	
31	    /** The soft capacity: the owner count at which a city starts warning of impending fullness. */
32	    static final long WARNING_THRESHOLD = 40;
33	
34	    private final ClinicService clinicService;
35	
36	    public CityCapacityWarningEvaluator(ClinicService clinicService) {
37	        this.clinicService = clinicService;
38	    }
39	
40	    /**
41	     * @param city the owner's city
42	     * @return {@code true} when {@code city} already contains between
43	     * {@value #WARNING_THRESHOLD} and {@link CityOwnerLimitValidator#MAX_OWNERS_PER_CITY} minus one
44	     * owners (inclusive), signalling it is approaching the capacity limit; {@code false} otherwise.
45	     */
46	    public boolean isApproachingCapacity(String city) {
47	        long count = this.clinicService.countOwnersInCity(city);
48	        return count >= WARNING_THRESHOLD && count < CityOwnerLimitValidator.MAX_OWNERS_PER_CITY;
49	    }
50	
51	    /**
52	     * @param city the owner's city
53	     * @return {@code true} when {@code city} already holds at least {@value #WARNING_THRESHOLD}
54	     * owners, i.e. it is at or over its soft capacity (whether or not it has also reached the hard
55	     * limit); {@code false} otherwise.
56	     */
57	    public boolean isOverSoftCapacity(String city) {
58	        return this.clinicService.countOwnersInCity(city) >= WARNING_THRESHOLD;
59	    }
60	}
