18	
19	import java.util.Locale;
20	import java.util.Set;
21	import java.util.stream.Collectors;
22	
23	import org.springframework.stereotype.Component;
24	import org.springframework.util.StringUtils;
25	
26	/**
27	 * Single source of truth for classifying an email address by the disposability of its domain.
28	 *
29	 * <p>A domain is <em>blocked</em> when it exactly matches a known disposable-email provider; such
30	 * addresses are rejected at creation (see {@link DisposableEmailDomainValidator}). A domain is
31	 * <em>disposable-adjacent</em> when it is not itself blocked yet shares its registrable name with a
32	 * blocked provider &mdash; for example {@code mailinator.net} or {@code x.tempmail.org}, which sit
33	 * next to a blocked domain on a different top-level domain or as a subdomain. Such addresses are
34	 * accepted but warrant a closer look.
35	 *
36	 * <p>All inputs are expected to be the already-normalized (trimmed, lower-cased) email produced by
37	 * {@link EmailNormalizer}; an absent email is classified as neither blocked nor adjacent.
38	 */
39	@Component
40	public class DisposableEmailDomainClassifier {
41	
42	    private static final Set<String> BLOCKED_DOMAINS =
43	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
44	
45	    /** The registrable labels (e.g. {@code mailinator}) of the blocked domains. */
46	    private static final Set<String> DISPOSABLE_BRANDS = BLOCKED_DOMAINS.stream()
47	        .map(DisposableEmailDomainClassifier::registrableLabel)
48	        .collect(Collectors.toUnmodifiableSet());
49	
50	    /**
51	     * @param email the normalized email address, or {@code null}/blank when none was supplied
52	     * @return {@code true} when the email's domain is on the disposable-provider blocklist
53	     */
54	    public boolean isBlocked(String email) {
55	        String domain = domainOf(email);
56	        return domain != null && BLOCKED_DOMAINS.contains(domain);
57	    }
58	
59	    /**
60	     * @param email the normalized email address, or {@code null}/blank when none was supplied
61	     * @return {@code true} when the email's domain is not itself blocked but shares its registrable
62	     * name with a blocked disposable-email provider (a different TLD or a subdomain of one)
63	     */
64	    public boolean isDisposableAdjacent(String email) {
65	        String domain = domainOf(email);
66	        if (domain == null || BLOCKED_DOMAINS.contains(domain)) {
67	            return false;
68	        }
69	        for (String label : domain.split("\\.")) {
70	            if (DISPOSABLE_BRANDS.contains(label)) {
71	                return true;
72	            }
73	        }
74	        return false;
75	    }
76	
77	    private static String domainOf(String email) {
78	        if (!StringUtils.hasText(email)) {
79	            return null;
80	        }
81	        int at = email.indexOf('@');
82	        if (at < 0) {
83	            return null;
84	        }
85	        return email.substring(at + 1).toLowerCase(Locale.ROOT);
86	    }
87	
88	    /** The label immediately left of the top-level domain (e.g. {@code mailinator} in {@code mailinator.com}). */
89	    private static String registrableLabel(String domain) {
90	        String[] labels = domain.split("\\.");
91	        return labels.length >= 2 ? labels[labels.length - 2] : domain;
92	    }
93	}
